declare(strict_types=1);use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$encoded=(string)($_REQUEST['SAMLRequest']??'');$relay=(string)($_REQUEST['RelayState']??'');if($encoded===''){http_response_code(400);Web::page('SAML','<section class="card narrow"><h1>Brak SAMLRequest</h1></section>');}try{$req=$saml->parseRequest($encoded);$_SESSION['pending_saml']=['request'=>$req,'relay_state'=>$relay,'created_at'=>time()];$user=$auth->currentUser();if(!$user)Web::redirect('/login?return='.rawurlencode('/saml/sso/resume'));Web::redirect('/saml/sso/resume');}catch(Throwable $e){http_response_code(400);Web::page('SAML','<section class="card narrow"><h1>Nieprawidłowe żądanie SAML</h1><div class="code">'.Web::e($e->getMessage()).'</div></section>',$auth->currentUser());}
